from math import comb


def fib(m: int) -> int:
    a, b = 0, 1
    for _ in range(m):
        a, b = b, a + b
    return a


def row_sum_A(n: int) -> int:
    return sum(comb(n + k, 2 * k) for k in range(n + 1))


def row_sum_B(n: int) -> int:
    return sum(comb(n + k, 2 * k + 1) for k in range(n + 1))


def verify_closed_forms(n_max: int = 15) -> None:
    for n in range(n_max + 1):
        a, b = row_sum_A(n), row_sum_B(n)
        assert a == fib(2 * n + 1), (n, a, fib(2 * n + 1))
        assert b == fib(2 * n), (n, b, fib(2 * n))
        print(f"n={n:2d}  A={a:6d}=fib({2*n+1})   B={b:6d}=fib({2*n})")
    print(f"verified A(n)=fib(2n+1) and B(n)=fib(2n) for n=0..{n_max}")


if __name__ == "__main__":
    verify_closed_forms()

from math import comb


def row_sum_A(n: int) -> int:
    return sum(comb(n + k, 2 * k) for k in range(n + 1))


def row_sum_B(n: int) -> int:
    return sum(comb(n + k, 2 * k + 1) for k in range(n + 1))


def cross_validate(n_max: int = 16) -> None:
    # coupled system
    a, b = 1, 0
    for n in range(n_max + 1):
        assert a == row_sum_A(n) and b == row_sum_B(n), n
        # three-term recurrence
        if n + 2 <= n_max:
            assert row_sum_A(n + 2) == 3 * row_sum_A(n + 1) - row_sum_A(n), n
        b2 = a + b          # B(n+1) = A(n) + B(n)
        a = a + b2          # A(n+1) = A(n) + B(n+1)
        b = b2
        print(f"n={n:2d}  A(n)={row_sum_A(n):6d}  "
              f"3A(n+1)-A(n)={3*row_sum_A(n+1)-row_sum_A(n):6d} = A(n+2)")
    print(f"coupled system and three-term recurrence verified to n={n_max}")


if __name__ == "__main__":
    cross_validate()
